package main

import (
    "context"
    "os"
    "github.com/larksuite/cli/cmd"
    "github.com/larksuite/cli/extension/command"
    "github.com/larksuite/cli/extension/credential"
)

type provider struct{}
func (provider) Name() string { return "synthetic-extension-host" }
func (provider) ResolveAccount(context.Context) (*credential.Account, error) {
    return &credential.Account{AppID: "synthetic-extension-app", Brand: credential.BrandFeishu, DefaultAs: credential.IdentityBot, SupportedIdentities: credential.SupportsBot}, nil
}
func (provider) ResolveToken(_ context.Context, spec credential.TokenSpec) (*credential.Token, error) {
    if spec.Type != credential.TokenTypeTAT { return nil, nil }
    return &credential.Token{Value: "synthetic-extension-token", Source: "fixture"}, nil
}

type args struct{}
type data struct { Value int `json:"value" schema:"required" doc:"fixture integer value"` }

func main() {
    credential.Register(provider{})
    contribution := command.Define(command.Definition[args, data]{
        Metadata: command.CommandMetadata{Service: command.DomainIm, Command: "+fixture-host", Description: "Return the synthetic host result", Risk: command.RiskRead,
            Authorization: command.AuthorizationDefinition{Identities: map[command.Identity]command.IdentityAuthorization{command.IdentityBot: {}}}},
        Hooks: command.Hooks[args, data]{Execute: func(context.Context, command.CommandContext, *args) (command.Result[data], error) {
            return command.Success(data{Value: 0}), nil
        }},
    })
    options := []cmd.BuildOption{cmd.WithCommandSets(command.Set{Domain: command.ExtendDomain(command.DomainIm), Commands: []command.Command{contribution}}), cmd.WithoutPlugins(), cmd.WithoutStrictMode(), cmd.WithoutServiceCommands()}
    // CANDIDATE_AGENT_OPTION
    os.Exit(cmd.ExecuteWithOptions(options...))
}
